import sys
import time

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.bus = smbus2.SMBus(busnum)
        self.address = address
        self.debug = debug

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            self.bus.write_i2c_block_data(self.address, 0x40 | (channel << 4), [0x03, pga >> 8, pga & 0xFF, sps >> 8, sps & 0xFF])
            time.sleep(0.002)
            data = self.bus.read_i2c_block_data(self.address, 3)
            return (data[0] << 16) | (data[1] << 8) | data[2]
        except Exception as e:
            if self.debug:
                print(f"Error: {e}")
            return None

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            self.bus.write_i2c_block_data(self.address, 0x40 | (channel << 4), [0x02, pga >> 8, pga & 0xFF, sps >> 8, sps & 0xFF])
        except Exception as e:
            if self.debug:
                print(f"Error: {e}")

    def get_last_conversion_results(self):
        try:
            data = self.bus.read_i2c_block_data(self.address, 3)
            return (data[0] << 16) | (data[1] << 8) | data[2]
        except Exception as e:
            if self.debug:
                print(f"Error: {e}")
            return None

