            if active_low:
                config |= 0x10
            if traditional_mode:
                config |= 0x20
            if latching:
                config |= 0x40
            self.bus.write_i2c_block_data(self.address, config, [pga >> 8, pga & 0xFF, sps >> 8, sps & 0xFF])
        except Exception as e:
            if self.debug:
                print(f"Error: {e}")

