class MCP3208:
    def __init__(self, channel):
        if channel < 0 or channel > 7:
            raise ValueError("Channel must be between 0 and 7")
        self.channel = channel
        self.spi = None

    def __enter__(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 1000000
            self.spi.mode = 0
        except Exception as e:
            print(f"Error opening SPI device: {e}")
            raise
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if self.spi:
            self.spi.close()

    def read(self):
        # Start bit, single-ended mode, and channel selection bits
        command = [1, 0, self.channel << 4]
        try:
            response = self.spi.xfer(command)
            # Combine the two 8-bit bytes into a 12-bit integer
            raw_value = (response[1] << 8) | response[2]
            return raw_value
        except Exception as e:
            print(f"Error reading from SPI device: {e}")
            raise

if __name__ == "__main__":
    with MCP3208(3) as adc:
        try:
            print(f"Raw value from channel 3: {adc.read()}")
        except Exception as e:
            print(f"An error occurred: {e}")

