import os
import signal
import time
import logging
import picamera2
import adafruit_imageload
import adafruit_imageload.gif
import gpiozero
import paho.mqtt.client as mqtt

class AnimatedGif:
    def __init__(self, display, width=None, height=None, folder_path=None):
        self.display = display
        self.width = width or display.width
        self.height = height or display.height
        self.folder_path = folder_path
        self.files = []
        self.frames = []
        self._is_running = False
        self._signal_handlers = []
        self._setup_signal_handlers()

    def _setup_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            handler = lambda sig=sig: self.stop()
            signal.signal(sig, handler)
            self._signal_handlers.append((sig, handler))

    def load_files(self):
        if not self.folder_path:
            raise FileNotFoundError("No folder path provided.")
        for filename in os.listdir(self.folder_path):
            if filename.endswith('.gif'):
                filepath = os.path.join(self.folder_path, filename)
                try:
                    with open(filepath, 'rb') as f:
                        loader = adafruit_imageload.gif.GifImageLoader(f)
                        if loader.is_animated:
                            self.files.append(filepath)
                except Exception as e:
                    logging.error(f"Error loading {filepath}: {e}")
        if not self.files:
            raise FileNotFoundError("No valid GIF files found.")

    def preload(self):
        for filepath in self.files:
            try:
                with open(filepath, 'rb') as f:
                    loader = adafruit_imageload.gif.GifImageLoader(f)
                    duration = loader.get_frame_duration(0)
                    loop_count = loader.get_loop_count()
                    for i in range(loader.frame_count):
                        frame = loader.frame(i)
                        frame = frame.convert('RGB')
                        frame = frame.resize((self.width, self.height), 0)
                        self.frames.append((frame, duration, loop_count))
            except Exception as e:
                logging.error(f"Error preloading {filepath}: {e}")

    def play(self):
        if not self.frames:
            return False
        for frame, duration, loop_count in self.frames:
            self.display.display(frame)
            elapsed_time = 0
            while elapsed_time < duration / 1000:
                sleep_time = max(0, duration / 1000 - elapsed_time)
                time.sleep(sleep_time)
                elapsed_time += sleep_time
        return True

    def run(self):
        self._is_running = True
        while self._is_running:
            try:
                self.load_files()
                self.preload()
                while self.play():
                    pass
            except Exception as e:
                logging.error(f"Error during animation: {e}")
            finally:
                self.frames = []

    def stop(self):
        self._is_running = False
        for sig, handler in self._signal_handlers:
            signal.signal(sig, signal.SIG_DFL)
        logging.info("Animation stopped.")

