class DHT20Sensor:
    def __init__(self):
        self.i2c = busio.I2C(board.SCL, board.SDA)
        self.dht = adafruit_dht.DHT20(self.i2c)
        time.sleep(0.5)

    def read_sensor(self):
        for _ in range(5):
            try:
                humidity = self.dht.humidity
                temperature = self.dht.temperature
                if humidity is not None and temperature is not None:
                    return (temperature, humidity, False)
                else:
                    logging.warning("Sensor data not available, retrying...")
                    time.sleep(2)
            except Exception as e:
                logging.error(f"Sensor read error: {e}")
                return (None, None, True)
        return (None, None, True)

    def cleanup(self):
        self.dht.exit()
        self.i2c.deinit()

