class DHT20Driver:
    def __init__(self):
        self._i2c = busio.I2C(board.SCL, board.SDA)
        self._dht = adafruit_dht.DHT20(self._i2c)
        self._last_read_time = 0
        self._temperature = None
        self._humidity = None

    def get_temperature_and_humidity(self):
        current_time = time.time()
        if current_time - self._last_read_time < 2:
            return self._temperature, self._humidity, False
        try:
            self._temperature, self._humidity = self._dht.temperature, self._dht.humidity
            self._last_read_time = current_time
            return self._temperature, self._humidity, False
        except (OSError, RuntimeError) as e:
            logging.warning("Failed to read from DHT20 sensor: %s", e)
            return None, None, True

    def close(self):
        self._dht.exit()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

if __name__ == "__main__":
    try:
        with DHT20Driver() as driver:
            while True:
                temperature, humidity, error = driver.get_temperature_and_humidity()
                if error:
                    print("Failed to read temperature and humidity.")
                else:
                    print(f"Temperature: {temperature}°C, Humidity: {humidity}%")
                time.sleep(1)
    except (KeyboardInterrupt, SystemExit):
        print("Exiting...")

import serial
import time
import logging

# Configure logging
logging.basicConfig(level=logging.DEBUG)

# Initialize serial connection
try:
    ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
except serial.SerialException as e:
    logging.error(f"Failed to open serial port: {e}")
    exit(1)

try:
    while True:
        try:
            # Read line from serial port
            line = ser.readline()
            if not line:
                logging.warning("No data received from sensor")
                continue

            # Decode line and split into temperature and humidity
            try:
                temp, humidity = line.decode('utf-8').strip().split(',')
                temp = float(temp)
                humidity = float(humidity)
            except ValueError as e:
                logging.error(f"Failed to parse data: {e}")
                continue

            # Check for alerts
            if temp > 30.0:
                logging.warning(f"Temperature alert: {temp}°C")
            if humidity > 70.0:
                logging.warning(f"Humidity alert: {humidity}%")

            # Print temperature and humidity
            print(f"{temp},{humidity}")

        except serial.SerialException as e:
            logging.error(f"Serial error: {e}")

        except Exception as e:
            logging.error(f"Unexpected error: {e}")

        # Pause before next reading
        time.sleep(1)

except KeyboardInterrupt:
    logging.info("Program interrupted by user")

finally:
    # Close serial connection
    if ser:
        ser.close()

