# Main loop
try:
    while True:
        for i, sensor in enumerate(sensors):
            try:
                if sensor.value:
                    print(f"Response for sensor {i+1}")
            except gpiozero.exc.DeviceRuntimeError as e:
                print(f"Error reading from sensor {i+1}: {e}")
        time.sleep(1)
except KeyboardInterrupt:
    exit_gracefully(None, None)

