class RequestHandler(BaseHTTPRequestHandler):
    def _set_response(self, code=200, content_type="text/html"):
        self.send_response(code)
        self.send_header("Content-type", content_type)
        self.end_headers()

    def do_GET(self):
        if self.path == "/":
            self._set_response()
            self.wfile.write(b"<html><body><a href='/light_on'>Turn LED on</a><br><a href='/light_off'>Turn LED off</a></body></html>")
        elif self.path == "/light_on":
            led.on()
            self._set_response()
            self.wfile.write(b"<html><body>LED is on. <a href='/'>Back</a></body></html>")
        elif self.path == "/light_off":
            led.off()
            self._set_response()
            self.wfile.write(b"<html><body>LED is off. <a href='/'>Back</a></body></html>")
        else:
            self._set_response(404)
            self.wfile.write(b"Not Found")

    def log_message(self, format, *args):
        return  # Disable logging

def run(server_class=HTTPServer, handler_class=RequestHandler, port=8080):
    server_address = ('0.0.0.0', port)
    httpd = server_class(server_address, handler_class)
    print(f"Starting httpd server on port {port}...")
    httpd.serve_forever()

