import time
import signal
import sys
import logging
import gpiozero
from datetime import datetime

class PIRSensor:
    def __init__(self, pin=17, debounce=2.0, sample_count=10):
        self.pin = pin
        self.debounce = debounce
        self.sample_count = sample_count
        self.last_trigger = 0
        self.events = []
        self.sensor = gpiozero.InputDevice(self.pin, pull_up=False)

    def start(self):
        self.sensor.when_activated = self._on_activated
        self.sensor.when_deactivated = self._on_deactivated

    def stop(self):
        self.sensor.close()

    def _on_activated(self):
        current_time = time.time()
        if current_time - self.last_trigger > self.debounce:
            self.last_trigger = current_time
            self.events.append(datetime.now().isoformat())

    def _on_deactivated(self):
        pass

    def get_stats(self):
        return {
            'total_events': len(self.events),
            'events': self.events
        }

def main():
    logging.basicConfig(level=logging.INFO)
    sensor = PIRSensor()
    try:
        sensor.start()
        while True:
            time.sleep(0.5)
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        sys.exit(1)
    finally:
        sensor.stop()

if __name__ == "__main__":
    main()

import logging
import time
import signal
import sys
import zmq
import gpiozero
import picamera2

class PIDHandler:
    def __init__(self):
        self.global_err_state = False
        self.last_msg = time.time()
        self.pwm = None
        self.digital = None
        self.watchdog_timeout = 20
        self.zmq_context = zmq.Context()
        self.zmq_socket = self.zmq_context.socket(zmq.SUB)
        self.zmq_socket.connect("tcp://localhost:5555")
        self.zmq_socket.setsockopt_string(zmq.SUBSCRIBE, '')
        self.setup_gpio()

    def setup_gpio(self):
        try:
            self.pwm = gpiozero.PWMLED(18, initial_value=0.0, frequency=1000)
            self.digital = gpiozero.LED(15)
        except RuntimeError:
            logging.error("Failed to initialize GPIO devices.")
            self.pwm = None
            self.digital = None

    def update_error_output(self):
        if self.pwm is not None:
            self.pwm.value = self.global_err_state
        if self.digital is not None:
            self.digital.value = self.global_err_state

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def handle_message(self):
        try:
            message = self.zmq_socket.recv_string(zmq.NOBLOCK)
            self.last_msg = time.time()
            # Process subscription callbacks here
        except zmq.error.Again:
            if time.time() - self.last_msg > self.watchdog_timeout:
                self.set_error_output(True)

    def cleanup(self):
        if self.pwm is not None:
            self.pwm.close()
        if self.digital is not None:
            self.digital.close()

def signal_handler(sig, frame):
    logging.info("Received signal to terminate.")
    handler.cleanup()
    sys.exit(0)

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    handler = PIDHandler()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        while True:
            handler.handle_message()
            time.sleep(0.1)
    except KeyboardInterrupt:
        logging.info("Exiting on keyboard interrupt.")
    finally:
        handler.cleanup()

