import RPi.GPIO as GPIO
import time

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        if pin_number < 0 or pin_number > 31:
            raise ValueError("Pin number must be between 0 and 31")
        if initial_value not in [0, 1]:
            raise ValueError("Initial value must be 0 or 1")
        self.pin_number = pin_number
        self.initial_value = initial_value
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.pin_number, GPIO.OUT, initial_value=self.initial_value)

    def set_value(self, value: int):
        if value not in [0, 1]:
            raise ValueError("Value must be 0 or 1")
        GPIO.output(self.pin_number, value)

    def shutdown(self):
        GPIO.cleanup(self.pin_number)

if __name__ == '__main__':
    try:
        pin = OutputPin(17, 0)
        for _ in range(10):
            pin.set_value(1)
            time.sleep(0.5)
            pin.set_value(0)
            time.sleep(0.5)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        pin.shutdown()

import RPi.GPIO as GPIO
import time
import sys

class RotaryEncoder:
    def __init__(self, clk, dt, callback=None, debounce=0.005):
        self.clk = clk
        self.dt = dt
        self.callback = callback
        self.debounce = debounce
        self.clk_last = None
        self.dt_last = None
        self.counter = 0
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.clk, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(self.dt, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.add_event_detect(self.clk, GPIO.BOTH, self._update, bouncetime=int(self.debounce * 1000))
        if self.callback is not None and not callable(self.callback):
            raise ValueError("callback must be callable")
        self.clk_last = GPIO.input(self.clk)
        self.dt_last = GPIO.input(self.dt)

    def _update(self, channel):
        clk = GPIO.input(self.clk)
        dt = GPIO.input(self.dt)
        if clk != self.clk_last:
            if clk == GPIO.HIGH:
                if dt != self.dt_last:
                    if dt == GPIO.LOW:
                        self.counter -= 1
                    else:
                        self.counter += 1
                    if self.callback is not None:
                        try:
                            self.callback(self.counter)
                        except Exception as e:
                            print(f"Exception in callback: {e}")
            self.clk_last = clk
        self.dt_last = dt

    def cleanup(self):
        GPIO.cleanup()

def cleanup():
    encoder.cleanup()

if __name__ == "__main__":
    try:
        encoder = RotaryEncoder(17, 18, callback=lambda x: print(f"Counter: {x}"))
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()

