import signal
import sys
import time
import gpiozero

class LEDController:
    def __init__(self, pin_number):
        try:
            self.led = gpiozero.LED(pin_number)
        except gpiozero.exc.DeviceRuntimeError as e:
            print(f"Error initializing LED: {e}")
            sys.exit(1)

    def on(self):
        self.led.on()

    def off(self):
        self.led.off()

    def blink(self, on_duration, off_duration):
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Durations must be non-negative.")
        while True:
            self.on()
            time.sleep(on_duration)
            self.off()
            time.sleep(off_duration)

def signal_handler(sig, frame):
    print("SIGINT/SIGTERM received, turning LED off.")
    controller.off()
    sys.exit(0)

if __name__ == "__main__":
    controller = LEDController(25)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        controller.blink(1.0, 0.5)
    except ValueError as e:
        print(f"Error in blink method: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

import json
import requests
import time
import gpiozero

# Initialize the button
button = gpiozero.Button(17, pull_up=True, bounce_time=0.1)

# Initialize the previous state of the button
prev_state = button.is_pressed

# Initialize the part_id
part_id = "PART-204"

# Initialize the defect_count
defect_count = 0

# Function to send the JSON report
def send_report(passed, defect_count):
    try:
        data = {
            "part_id": part_id,
            "passed": passed,
            "defect_count": defect_count
        }
        headers = {
            "Content-Type": "application/json"
        }
        response = requests.post("http://localhost:8000/quality", data=json.dumps(data), headers=headers, timeout=5)
        if response.status_code == 200:
            print("Report sent successfully.")
        else:
            print(f"Failed to send report. HTTP Status Code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Failed to send report. Error: {e}")

# Main loop
while True:
    try:
        # Check the state of the button
        if button.is_pressed != prev_state:
            # If the button state has changed, send the report
            if button.is_pressed:
                send_report(False, 1)
            else:
                send_report(True, 0)
            # Update the previous state of the button
            prev_state = button.is_pressed
        # Wait for 2 seconds before checking the button state again
        time.sleep(2)
    except KeyboardInterrupt:
        # Clean up the GPIO resources on exit
        button.close()
        print("Exiting...")
        break

