            self._bus.deinit()
            self._bus = None
        if self._rtc is not None:
            self._rtc.deinit()
            self._rtc = None

    def read_all(self):
        try:
            raw = self._rtc.datetime
            return (
                raw.tm_year - 1900,
                raw.tm_mon,
                raw.tm_mday,
                raw.tm_wday,
                raw.tm_hour,
                raw.tm_min,
                raw.tm_sec,
            )
        except IOError as e:
            raise IOError("Failed to read RTC: {}".format(e))

    def read_datetime(self):
        try:
            raw = self._rtc.datetime
            return datetime.datetime(
                raw.tm_year + 1900,
                raw.tm_mon,
                raw.tm_mday,
                raw.tm_hour,
                raw.tm_min,
                raw.tm_sec,
                tzinfo=datetime.timezone.utc,
            )
        except IOError as e:
            raise IOError("Failed to read RTC: {}".format(e))

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        try:
            if not (2000 <= year <= 2099):
                raise ValueError("Year must be between 2000 and 2099")
            if not (1 <= month <= 12):
                raise ValueError("Month must be between 1 and 12")
            if not (1 <= date <= 31):
                raise ValueError("Date must be between 1 and 31")
            if not (0 <= day <= 6):
                raise ValueError("Day must be between 0 and 6")
            if not (0 <= hours <= 23):
                raise ValueError("Hours must be between 0 and 23")
            if not (0 <= minutes <= 59):
                raise ValueError("Minutes must be between 0 and 59")
            if not (0 <= seconds <= 59):
                raise ValueError("Seconds must be between 0 and 59")
            self._rtc.datetime = datetime.datetime(
                year + 1900,
                month,
                date,
                hours,
                minutes,
                seconds,
                tzinfo=datetime.timezone.utc,
            )
        except IOError as e:
            raise IOError("Failed to write RTC: {}".format(e))

    def write_datetime(self, dt):
        try:
            self._rtc.datetime = dt
        except IOError as e:
            raise IOError("Failed to write RTC: {}".format(e))

    def write_now(self):
        try:
            self._rtc.datetime = datetime.datetime.now(datetime.timezone.utc)
        except IOError as e:
            raise IOError("Failed to write RTC: {}".format(e))

if __name__ == "__main__":
