import serial
import signal
import sys
import time
from dataclasses import dataclass
from gpiozero import CPUTemperature
from picamera2 import Picamera2
from adafruit_bme280 import basic as adafruit_bme280
from paho.mqtt import client as mqtt_client

# Define the GPS_readings dataclass
@dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: float
    satellites: int

class GPSReader:
    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
        except serial.SerialException as e:
            print(f"Failed to open {self.port}: {e}")
            sys.exit(1)

    def disconnect(self):
        if self.ser:
            self.ser.close()
            self.ser = None

    def read_gps(self):
        while True:
            try:
                line = self.ser.readline().decode('utf-8').strip()
                if line.startswith("$GPGGA"):
                    fields = line.split(',')
                    if len(fields) == 15 and fields[2] != '' and fields[4] != '' and fields[9] != '':
                        lat_degrees = int(fields[2][:2])
                        lat_minutes = float(fields[2][2:])
                        lat = lat_degrees + lat_minutes / 60.0
                        if fields[3] == 'S':
                            lat = -lat
                        lon_degrees = int(fields[4][:3])
                        lon_minutes = float(fields[4][3:])
                        lon = lon_degrees + lon_minutes / 60.0
                        if fields[5] == 'W':
                            lon = -lon
                        altitude = float(fields[9])
                        satellites = int(fields[7])
                        return GPS_readings(latitude=lat, longitude=lon, altitude=altitude, satellites=satellites)
            except (serial.SerialTimeoutException, ValueError, IndexError) as e:
                print(f"Error reading GPS data: {e}")
                continue

def signal_handler(sig, frame):
    print('Interrupt received, cleaning up...')
    gps_reader.disconnect()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    gps_reader = GPSReader()
    gps_reader.connect()

    try:
        while True:
            reading = gps_reader.read_gps()
            print(f"Latitude: {reading.latitude}, Longitude: {reading.longitude}, Altitude: {reading.altitude}, Satellites: {reading.satellites}")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        gps_reader.disconnect()

import serial
import time
import signal
import sys

class ESP8266:
    def __init__(self, port='/dev/serial0', baudrate=115200):
        self.port = port
        self.baudrate = baudrate
        self.ser = None

    def __enter__(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=5, write_timeout=5)
            self.ser.set_buffer_size(rx_size=4096, tx_size=4096)
        except serial.SerialException as e:
            print(f"Failed to open serial port: {e}")
            sys.exit(1)
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if self.ser:
            self.ser.close()

    def _send_command(self, command, delay=1, max_retries=3):
        for _ in range(max_retries):
            self.ser.write(command.encode())
            time.sleep(delay)
            response = self.ser.read_until(b'\r\n', timeout=5).decode()
            if "OK" in response or "ERROR" in response or "FAIL" in response:
                return response
        return None

    def test_connection(self):
        response = self._send_command("AT\r\n")
        return response == "OK"

    def restart(self):
        response = self._send_command("AT+RST\r\n")
        time.sleep(2)
        return response == "ready"

    def connect_wifi(self, ssid, password):
        command = f"AT+CWJAP_CUR=\"{ssid}\",\"{password}\"\r\n"
        response = self._send_command(command)
        return "WIFI GOT IP" in response

# Example usage:
if __name__ == "__main__":
    with ESP8266() as esp:
        if esp.test_connection():
            print("Connection test passed.")
        else:
            print("Connection test failed.")
        if esp.restart():
            print("Restart command sent successfully.")
        else:
            print("Restart command failed.")
        if esp.connect_wifi("your_ssid", "your_password"):
            print("Connected to Wi-Fi.")
        else:
            print("Failed to connect to Wi-Fi.")

import serial
import time
import signal
import sys

class GPSModule:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        self.port = port
        self.baud = baud
        self.ser = None
        try:
            self.ser = serial.Serial(self.port, self.baud, timeout=1)
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to open port {self.port}: {e}")

    def attach(self):
        self.ser.write(b"AT+CGNSPWR=1\r\n")
        time.sleep(1)
        if self.ser.out_waiting == 0:
            raise RuntimeError("Failed to send power on command")

    def detach(self):
        self.ser.write(b"AT+CGNSPWR=0\r\n")
        if self.ser.out_waiting == 0:
            raise RuntimeError("Failed to send power off command")

    def get_data(self):
        while self.ser.in_waiting > 0:
            line = self.ser.readline().decode('utf-8').strip()
            if line.startswith("$GPRMC") and len(line.split(',')) > 2 and line.split(',')[2] == "A":
                return line.split(',')
        return None

    def close(self):
        if self.ser:
            self.ser.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

def signal_handler(sig, frame):
    print('Closing GPS module...')
    gps.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

gps = GPSModule()
try:
    with gps as g:
        g.attach()
        while True:
            data = g.get_data()
            if data:
                print(data)
except Exception as e:
    print(f"An error occurred: {e}")
finally:
    gps.close()

