import logging
import serial
import time

class SimpleGPS:
    def __init__(self):
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial('/dev/serial0', 9600, timeout=1)
            return True
        except OSError:
            logging.error("Failed to open serial port.")
            return False

    def read_data(self):
        if self.ser is None:
            return None
        try:
            line = self.ser.readline().decode('utf-8').strip()
            if not line:
                return None
            return line
        except (UnicodeDecodeError, serial.SerialException):
            return None

    def parse_gga(self, line):
        if not line.startswith('$GPGGA') and not line.startswith('$GNGGA'):
            return None
        try:
            fields = line.split(',')
            utc_time = fields[1]
            latitude = self._parse_coordinate(fields[2], fields[3])
            longitude = self._parse_coordinate(fields[4], fields[5])
            fix_quality = fields[6]
            num_satellites = fields[7]
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError):
            return None

    def _parse_coordinate(self, degrees, direction):
        if degrees == '':
            return None
        degrees = float(degrees)
        minutes = (degrees - int(degrees)) * 100 / 60
        return int(degrees) + minutes if direction == 'N' or direction == 'E' else -int(degrees) - minutes

    def close(self):
        if self.ser is not None:
            try:
                self.ser.close()
            except Exception:
                pass
            self.ser = None

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    gps = SimpleGPS()
    if not gps.connect():
        logging.error("Failed to connect to GPS module.")
        exit(1)

    try:
        while True:
            line = gps.read_data()
            if line and line.startswith('$GPGGA') or line.startswith('$GNGGA'):
                data = gps.parse_gga(line)
                if data:
                    logging.info(f"Parsed data: {data}")
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Shutting down.")
    finally:
        gps.close()

