import serial
import datetime
import sys

class SmartMeterReader:
    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout

    def __enter__(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
        except OSError as e:
            print(f"Failed to open serial port {self.port}: {e}", file=sys.stderr)
            raise
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if self.ser:
            self.ser.close()

    def read_and_log(self, log_file):
        while True:
            line = self.ser.readline()
            if not line:
                continue
            try:
                power = float(line.decode('utf-8').strip())
            except ValueError:
                print("Non-numeric data received, skipping...", file=sys.stderr)
                continue
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            log_entry = f"{timestamp} - Power: {power} W\n"
            try:
                with open(log_file, 'a') as f:
                    f.write(log_entry)
            except OSError as e:
                print(f"Failed to write to log file {log_file}: {e}", file=sys.stderr)
                continue

if __name__ == "__main__":
    try:
        with SmartMeterReader() as reader:
            reader.read_and_log('power_consumption.log')
    except KeyboardInterrupt:
        print("Program interrupted by user.")
